// Binary Search using Recursive Call Stack
int binarySearch(int arr[], int low, int high, int key) {
    if (low > high) return -1; // Base case: तत्त्व नहीं मिला
    int mid = low + (high - low) / 2;
    if (arr[mid] == key) return mid; // तत्त्व मिल गया
    if (arr[mid] > key) return binarySearch(arr, low, mid - 1, key); // बायाँ भाग
    return binarySearch(arr, mid + 1, high, key); // दायाँ भाग
}

