class BTreeNode:
    def __init__(self, leaf=False):
        self.leaf = leaf           # నోడ్ లీఫ్ (చివరి నోడ్) కాదా అని సూచిస్తుంది
        self.keys = []           # డిస్క్ బ్లాక్‌లో నిల్వ చేయబడిన క్రమబద్ధీకరించిన కీలు
        self.children = []       # చైల్డ్ నోడ్ పాయింటర్లు (బ్లాక్ అడ్రస్‌లు)

class BTree:
    def __init__(self, t):
        self.root = BTreeNode(True)
        self.t = t               # కనీస డిగ్రీ (Minimum Degree - డిస్క్ బ్లాక్ సామర్థ్యంపై ఆధారపడి ఉంటుంది)

    def search(self, k, node=None):
        # కీ (key) ఆధారంగా డిస్క్ బ్లాక్‌ను శోధించే మెకానిజం
        if node is None:
            node = self.root

        i = 0
        # నోడ్‌లోని కీలలో సరిపోయే స్థానాన్ని వెతకడం
        while i < len(node.keys) and k > node.keys[i]:
            i += 1

        # కీ కనుగొనబడితే ప్రస్తుత నోడ్ మరియు ఇండెక్స్ రిటర్న్ అవుతాయి
        if i < len(node.keys) and k == node.keys[i]:
            return (node, i)

        # లీఫ్ నోడ్ అయితే మరియు కీ లేకపోతే, ఫైల్ రికార్డ్ లేనట్లు
        if node.leaf:
            return None

        # చైల్డ్ బ్లాక్‌ను డిస్క్ నుండి లోడ్ చేసి రికర్సివ్‌గా శోధించడం
        return self.search(k, node.children[i])

# B-Tree సృష్టి: డిగ్రీ t = 3 (డిస్క్ బ్లాక్ సైజును బట్టి)
